         them in the extracted set. -->
    <span v-if="false" data-test="i18n-discoverable-list">
      {{ $t('validation_show_details') }}
      {{ $t('validation_col_details') }}
      {{ $t('validation_filter_version') }}
      {{ $t('validation_policy_versions_title') }}
      {{ $t('validation_policy_versions_subtitle') }}
      {{ $t('validation_policy_profiles_title') }}
      {{ $t('validation_policy_profiles_subtitle') }}
      {{ $t('validation_status_current') }}
      {{ $t('validation_status_deprecated') }}
      {{ $t('validation_status_eol') }}
      {{ $t('validation_severity_fatal') }}
      {{ $t('validation_severity_error') }}
      {{ $t('validation_severity_warning') }}
      {{ $t('validation_severity_info') }}
      {{ $t('validation_severity_default_label') }}
    </span>
    <div class="page-header">
      <h2 class="page-title">{{ $t('validation_rules_page_title') }}</h2>
