        >
          {{ row.layer }}
        </q-chip>
      </template>

      <template #body-cell-effective_severity="{ row }">
        <div class="severity-cell">
          <q-select
            dense
            outlined
            v-model="row.effective_severity"
            :options="severityOptions"
            emit-value
            map-options
            :data-test="`row-severity-${row.code}`"
            :class="
