          />
        </div>
        <div
          v-if="row.override"
          class="text-caption text-grey-7"
          :data-test="`row-default-${row.code}`"
        >
          {{ $t('validation_default_severity_label') }}: {{ row.default_severity }}
        </div>
      </template>

    </DocBitsTable>

    <!-- BOL-424: rule detail dialog. Opened from the row "Details" button. -->
    <q-dialog v-model="detailDialogOpen" no-backdrop-dismiss>
      <q-card class="rule-detail-dialog" data-test="rule-detail-dialog">
        <q-card-section class="detail-dialog-header q-pa-md">
          <div class="detail-header-row">
            <q-chip
              v-if="detailRow"
              dense
              :class="`layer-chip layer-${detailRow.layer.toLowerCase()}`"
            >
              {{ detailRow.layer }}
            </q-chip>
            <code class="detail-dialog-code">{{ detailRow?.code }}</code>
            <q-space />
            <q-btn
              flat
              dense
              round
              icon="close"
              data-test="rule-detail-close"
              @click="detailDialogOpen = false"
            />
