            </span>
            <span v-if="detailRow.version" class="meta-item">
              <span class="meta-label">{{ $t('validation_col_version') }}</span>
              <span class="meta-value">{{ detailRow.version }}</span>
            </span>
            <span class="meta-item">
              <span class="meta-label">{{ $t('validation_severity_default_label') }}</span>
              <span :class="['meta-pill', `pill-${detailRow.default_severity}`]">
                {{ severityLabel(detailRow.default_severity) }}
