<script lang="ts">
import { defineComponent } from 'vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions/index';
import { docTypeApiService, validationRulesApiService } from 'src/services';
import type {
  ProfileRegistryEntry,
  RuleSeverity,
  ValidationRuleRow,
  VersionRegistryEntry,
} from 'src/services/settings/ValidationRulesApiService';
import AcceptancePolicyCard from 'src/pages/Settings/Components/ValidationRules/AcceptancePolicyCard.vue';
import SeverityLegendCard from 'src/pages/Settings/Components/ValidationRules/SeverityLegendCard.vue';
import RuleDetailBox from 'src/pages/Settings/Components/ValidationRules/RuleDetailBox.vue';

interface Filter {
  layer: string | null;
  profile: string | null;
  versions: string[];
  search: string;
}

// BOL-429: per-DocType acceptance policy. Today the Settings page
// scopes the policy to the INVOICE doc-type (the only DocType that
// can have XRECHNUNG_VALIDATION_ENABLED on it). When we expand to
// CREDIT_NOTE/etc. the doc-type selector lives here.
const POLICY_DOC_TYPE = 'INVOICE';
const ATTR_ACCEPTED_VERSIONS = 'XRECHNUNG_ACCEPTED_VERSIONS';
const ATTR_ACCEPTED_PROFILES = 'ZUGFERD_ACCEPTED_PROFILES';

interface PolicyEntry {
  key: string;
  label: string;
  note?: string | null;
  releasedOn?: string | null;
  statusChip?: { label: string; color: string; textColor: string } | null;
}

export default defineComponent({
  name: 'ValidationRulesList',
  components: {
    DocBitsTable,
    AcceptancePolicyCard,
    SeverityLegendCard,
    RuleDetailBox,
  },
  data() {
    return {
      loading: false,
      allRows: [] as ValidationRuleRow[],
      filter: {
        layer: null,
        profile: null,
        versions: [] as string[],
        search: '',
      } as Filter,
      severityOptions: [
        { label: 'Fatal', value: 'fatal' as RuleSeverity },
        { label: 'Error', value: 'error' as RuleSeverity },
        { label: 'Warning', value: 'warning' as RuleSeverity },
        { label: 'Info', value: 'info' as RuleSeverity },
      ],
      detailDialogOpen: false,
      detailRow: null as ValidationRuleRow | null,

      // BOL-429: acceptance policy state
      policyLoading: true,
      versionRegistry: [] as VersionRegistryEntry[],
      profileRegistry: [] as ProfileRegistryEntry[],
      acceptedVersions: [] as string[],
      acceptedProfiles: [] as string[],
      savingPolicyKind: null as 'versions' | 'profiles' | null,
    };
  },
  computed: {
    layerOptions() {
      return ['L0', 'L0b', 'L0c', 'L1', 'L2', 'L3', 'L4'].map((v) => ({
        label: v,
        value: v,
      }));
    },
    profileOptions() {
      const profiles = new Set(this.allRows.map((r) => r.profile));
      return Array.from(profiles)
        .sort()
        .map((p) => ({ label: p, value: p }));
    },
    versionFilterOptions() {
      // Distinct versions actually present in the catalog.
      const versions = new Set(
        this.allRows
          .map((r) => r.version)
          .filter((v): v is string => v !== null && v !== undefined),
      );
      return Array.from(versions)
        .sort()
        .map((v) => ({ label: v, value: v }));
    },
    overrideCount(): number {
      return this.allRows.filter((r) => r.override).length;
    },
    versionEntries(): PolicyEntry[] {
      return this.versionRegistry.map((v) => ({
        key: v.version,
        label: v.label,
        note: v.note,
        releasedOn: v.released_on,
        statusChip: this.statusChip(v.status),
      }));
    },
    profileEntries(): PolicyEntry[] {
      return this.profileRegistry.map((p) => ({
        key: p.profile,
        label: p.label,
        note: p.note,
        statusChip: p.en16931_conformant
          ? null
          : {
              label: this.$t('validation_policy_not_en16931'),
              color: 'amber-2',
              textColor: 'amber-9',
            },
      }));
    },
    columns(): any[] {
      return [
        {
          name: 'expand',
          label: this.$t('validation_col_details'),
          field: () => '',
          align: 'center',
          style: 'width: 130px',
          headerStyle: 'width: 130px',
        },
        {
          name: 'layer',
          label: this.$t('validation_col_layer'),
          field: 'layer',
          align: 'left',
          sortable: true,
        },
        {
          name: 'code',
          label: this.$t('validation_col_code'),
          field: 'code',
          align: 'left',
          sortable: true,
          classes: 'col-mono',
        },
        {
          name: 'profile',
          label: this.$t('validation_col_profile'),
          field: 'profile',
          align: 'left',
          sortable: true,
        },
        {
          name: 'version',
          label: this.$t('validation_col_version'),
          field: (row: ValidationRuleRow) => row.version || '—',
          align: 'left',
          sortable: true,
        },
        {
          name: 'field',
          label: this.$t('validation_col_field'),
          field: (row: ValidationRuleRow) => row.field || '—',
          align: 'left',
        },
        {
          name: 'effective_severity',
          label: this.$t('validation_col_severity'),
          field: 'effective_severity',
          align: 'left',
          sortable: true,
        },
      ];
    },
    filteredRows(): ValidationRuleRow[] {
      const search = this.filter.search.trim().toLowerCase();
      const versions = new Set(this.filter.versions);
      return this.allRows.filter((r) => {
        if (this.filter.layer && r.layer !== this.filter.layer) return false;
        if (this.filter.profile && r.profile !== this.filter.profile) return false;
        if (versions.size > 0) {
          if (!r.version || !versions.has(r.version)) return false;
        }
        if (search) {
          const haystack =
            `${r.code} ${r.field || ''} ${r.profile} ${r.description || ''}`.toLowerCase();
          if (!haystack.includes(search)) return false;
        }
        return true;
      });
    },
  },
  mounted() {
    this.load();
    this.loadPolicy();
  },
  methods: {
    statusChip(status: 'current' | 'deprecated' | 'eol') {
      if (status === 'current') {
        return {
          label: this.$t('validation_status_current'),
          color: 'green-2',
          textColor: 'green-9',
        };
      }
      if (status === 'deprecated') {
        return {
          label: this.$t('validation_status_deprecated'),
          color: 'amber-2',
          textColor: 'amber-9',
        };
      }
      return {
        label: this.$t('validation_status_eol'),
        color: 'red-2',
        textColor: 'red-9',
      };
    },
    hasDetails(row: ValidationRuleRow): boolean {
      return Boolean(
        row.description ||
          row.method ||
          row.triggered_when ||
          row.example_valid ||
          row.example_invalid ||
          (row.references && row.references.length) ||
          row.rationale,
      );
    },
    openDetail(row: ValidationRuleRow) {
      this.detailRow = row;
      this.detailDialogOpen = true;
    },
    severityLabel(severity: RuleSeverity | null): string {
      if (!severity) return '—';
      const map: Record<string, string> = {
        fatal: this.$t('validation_severity_fatal'),
        error: this.$t('validation_severity_error'),
        warning: this.$t('validation_severity_warning'),
        info: this.$t('validation_severity_info'),
      };
      return map[severity] || severity;
    },
    async load() {
      this.loading = true;
      try {
        const resp = await validationRulesApiService.list();
        this.allRows = resp?.data || [];
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.loading = false;
      }
    },
    async loadPolicy() {
      this.policyLoading = true;
      try {
        const [registries, attrs] = await Promise.all([
          validationRulesApiService.listVersions(),
          docTypeApiService.getAttributesByDocKey({
            doc_type: POLICY_DOC_TYPE,
          }),
        ]);
        this.versionRegistry = registries.versions || [];
        this.profileRegistry = registries.profiles || [];
        this.acceptedVersions = this.parseJsonAttr(
          attrs,
          ATTR_ACCEPTED_VERSIONS,
        );
        this.acceptedProfiles = this.parseJsonAttr(
          attrs,
          ATTR_ACCEPTED_PROFILES,
        );
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.policyLoading = false;
      }
    },
    parseJsonAttr(attrsResponse: any, key: string): string[] {
      const list = attrsResponse?.data || attrsResponse?.attributes || [];
      const found = list.find?.((a: any) => a.attribute_key === key);
      const raw = found?.attribute_value;
      if (!raw) return [];
      try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed)
          ? parsed.map((v: any) => String(v))
          : [];
      } catch {
        return [];
      }
    },
    async savePolicy(kind: 'versions' | 'profiles', accepted: string[]) {
      this.savingPolicyKind = kind;
      const attributeKey =
        kind === 'versions' ? ATTR_ACCEPTED_VERSIONS : ATTR_ACCEPTED_PROFILES;
      try {
        await docTypeApiService.setAttribute({
          doc_type: POLICY_DOC_TYPE,
          attribute_key: attributeKey,
          attribute_value: JSON.stringify(accepted),
        });
        if (kind === 'versions') {
          this.acceptedVersions = [...accepted];
        } else {
          this.acceptedProfiles = [...accepted];
        }
        notify.success(this.$t('validation_policy_saved'));
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.savingPolicyKind = null;
      }
    },
    async onSeverityChange(row: ValidationRuleRow, value: RuleSeverity | null) {
      // Optimistic UI: flip the row immediately, revert on failure.
      const previousEffective = row.effective_severity;
      const previousOverride = row.override;
      row.override = value;
      row.effective_severity = value || row.default_severity;

      try {
        await validationRulesApiService.setOverride(row.code, value);
        notify.success(this.$t('validation_override_saved'));
      } catch (err) {
        row.override = previousOverride;
        row.effective_severity = previousEffective;
        notify.error(ApiExceptions.getErrorMessage(err as any));
      }
    },
    async onResetAllOverrides() {
      const overridden = this.allRows.filter((r) => r.override);
      if (overridden.length === 0) return;
      const confirmed = window.confirm(
        this.$t('validation_reset_all_confirm', {
          count: overridden.length,
        }),
      );
      if (!confirmed) return;

      // Snapshot for revert
      const snapshot = overridden.map((r) => ({
        row: r,
        prevEffective: r.effective_severity,
        prevOverride: r.override,
      }));

      // Optimistic clear
      for (const s of snapshot) {
        s.row.override = null;
        s.row.effective_severity = s.row.default_severity;
      }

      const failed: typeof snapshot = [];
      await Promise.allSettled(
        snapshot.map(async (s) => {
          try {
            await validationRulesApiService.setOverride(s.row.code, null);
          } catch (err) {
            failed.push(s);
          }
        }),
      );

      if (failed.length === 0) {
        notify.success(
          this.$t('validation_reset_all_success', { count: snapshot.length }),
        );
      } else {
        // Revert the failed ones
        for (const s of failed) {
          s.row.override = s.prevOverride;
          s.row.effective_severity = s.prevEffective;
        }
        notify.error(
          this.$t('validation_reset_all_partial_failure', {
            failed: failed.length,
            total: snapshot.length,
          }),
        );
      }
    },
  },
});
</script>

