<template>
  <q-card
    v-if="!dismissed"
    class="severity-legend-card q-mb-md"
    flat
    bordered
    data-test="severity-legend-card"
  >
    <q-card-section class="row items-center q-pa-md">
      <q-icon name="info" size="20px" color="primary" class="q-mr-md" />
      <div class="legend-title text-weight-medium">
        {{ $t('validation_severity_legend_title') }}
      </div>
      <q-space />
      <q-btn
        flat
        dense
        round
        icon="close"
        size="sm"
        :title="$t('dismiss')"
        data-test="severity-legend-dismiss"
        @click="dismiss"
      />
    </q-card-section>
    <q-separator />
    <q-card-section class="severity-legend-grid q-pa-md">
      <div
        v-for="entry in entries"
        :key="entry.key"
        class="legend-row"
        :data-test="`severity-legend-${entry.key}`"
      >
        <q-chip
          dense
          square
          :class="`severity-pill severity-${entry.key}`"
        >
          {{ $t(entry.labelKey) }}
        </q-chip>
        <span class="legend-text text-grey-8">
          {{ $t(entry.descriptionKey) }}
        </span>
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

const STORAGE_KEY = 'einvoice_validation_severity_legend_dismissed_v1';

interface LegendEntry {
  key: 'fatal' | 'error' | 'warning' | 'info';
  labelKey: string;
  descriptionKey: string;
}

const ENTRIES: LegendEntry[] = [
  {
    key: 'fatal',
    labelKey: 'validation_severity_fatal',
    descriptionKey: 'validation_severity_fatal_desc',
  },
  {
    key: 'error',
    labelKey: 'validation_severity_error',
    descriptionKey: 'validation_severity_error_desc',
  },
  {
    key: 'warning',
    labelKey: 'validation_severity_warning',
    descriptionKey: 'validation_severity_warning_desc',
  },
  {
    key: 'info',
    labelKey: 'validation_severity_info',
    descriptionKey: 'validation_severity_info_desc',
  },
];

export default defineComponent({
  name: 'SeverityLegendCard',
  data() {
    return {
      dismissed: false,
      entries: ENTRIES,
    };
  },
  mounted() {
    try {
      this.dismissed = window.localStorage.getItem(STORAGE_KEY) === '1';
    } catch {
      this.dismissed = false;
    }
  },
  methods: {
    dismiss() {
      this.dismissed = true;
      try {
        window.localStorage.setItem(STORAGE_KEY, '1');
      } catch {
        // localStorage unavailable — non-critical, just don't persist.
      }
    },
  },
});
</script>

